/**
 * Responsive AVIF/WebP image from the sets generated by scripts/images.mjs.
 * Width and height are always set, so the browser reserves the box before the
 * file arrives and nothing shifts. Only an above-the-fold image should pass
 * `priority`.
 */
export default function Picture({
  image,
  alt,
  sizes = '100vw',
  priority = false,
  className = '',
  imgClassName = '',
  style,
}) {
  const { name, widths, width, height } = image
  const set = (ext) => widths.map((w) => `/img/${name}-${w}.${ext} ${w}w`).join(', ')
  const largest = widths[widths.length - 1]

  return (
    <picture className={className}>
      <source type="image/avif" srcSet={set('avif')} sizes={sizes} />
      <source type="image/webp" srcSet={set('webp')} sizes={sizes} />
      <img
        src={`/img/${name}-${largest}.webp`}
        alt={alt}
        width={width}
        height={height}
        loading={priority ? 'eager' : 'lazy'}
        decoding="async"
        fetchpriority={priority ? 'high' : undefined}
        className={imgClassName}
        style={style}
      />
    </picture>
  )
}
